/**
 * Invalid frozen request fields, period, recipe identity/digest, explicit confirmation, policy gates or verified-run binding; nothing is published
 */
export type ExperimentInvalidInputResponse = GoodwillExperimentError;

/**
 * Approved operator sign-in required; persona labels do not authorize access
 */
export type ExperimentUnauthorizedResponse = GoodwillExperimentError;

/**
 * Separate execution/spending authorization or explicit process-owner review authority is missing
 */
export type ExperimentForbiddenResponse = GoodwillExperimentError;

/**
 * Recipe/approval metadata or the required verified acquisition run was not found
 */
export type ExperimentNotFoundResponse = GoodwillExperimentError;

/**
 * Recipe provenance or local synthetic source is unavailable, or the acquisition worker is busy
 */
export type ExperimentConflictResponse = GoodwillExperimentError;

/**
 * Experiment metadata, initialization or authorization service is unavailable; no data has been published
 */
export type ExperimentUnavailableResponse = GoodwillExperimentError;

/**
 * Unknown resource
 */
export type NotFoundResponse = ReportingError;

/**
 * State, overlap, correction or concurrency conflict; last-good remains unchanged
 */
export type ConflictResponse = ReportingError;

/**
 * Report exceeds the supervised foundation size limit
 */
export type ReportTooLargeResponse = ReportingError;

/**
 * Storage failed; last successful publication has not been replaced
 */
export type StorageUnavailableResponse = ReportingError;

/**
 * Invalid request; last successful publication is unchanged
 */
export type InvalidInputResponse = ReportingError;

